package escuela.disenoportales;
import escuela.seguridad.service.UsuarioPrincipal;
import escuela.common.exception.ReglaNegocioException;
import escuela.sitioweb.SitioService;
import escuela.archivo.repository.ArchivoRepository;
import escuela.archivo.storage.AlmacenamientoArchivo;
import escuela.archivo.entity.EstadoArchivo;
import escuela.institucion.repository.InstitucionRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
import javax.imageio.ImageIO;
import java.io.*;

@Service @RequiredArgsConstructor @Transactional
public class PortalIdentidadService {
 private final JdbcTemplate jdbc;private final SitioService sitios;private final InstitucionRepository instituciones;private final ArchivoRepository archivos;private final AlmacenamientoArchivo almacenamiento;
 public record Tema(String codigo,PortalTipo portal,long version,Long publicadaVersion,String principal,String fondo,String acento,boolean original,String nombre,byte[] logo,String oscuroPrincipal,String oscuroFondo,String oscuroAcento){
  public String getVariables(){return (original&&portal==PortalTipo.ADMIN?PortalColores.variables(PortalTipo.ADMIN.principal,PortalTipo.ADMIN.fondo,PortalTipo.ADMIN.acento):PortalColores.variables(principal,fondo,acento))+(original||oscuroPrincipal==null?"":"--pi-dark-principal:"+oscuroPrincipal+";--pi-dark-fondo:"+oscuroFondo+";--pi-dark-acento:"+oscuroAcento+";");}public boolean isTieneLogo(){return logo!=null;}public String getCodigo(){return codigo;}public String getNombre(){return nombre;}public PortalTipo getPortal(){return portal;}public long getVersion(){return version;}public Long getPublicadaVersion(){return publicadaVersion;}public String getPrincipal(){return principal;}public String getFondo(){return fondo;}public String getAcento(){return acento;}public boolean isOriginal(){return original;}
  public String getOscuroPrincipal(){return oscuroPrincipal;}public String getOscuroFondo(){return oscuroFondo;}public String getOscuroAcento(){return oscuroAcento;}
  public boolean isUsarPaleta(){return !original||portal==PortalTipo.ADMIN;}
  public String getEstado(){return version>(publicadaVersion==null?0:publicadaVersion)?"Cambios sin publicar":publicadaVersion==null?"Diseño original":"Publicado";}
 }
 public void autorizar(UsuarioPrincipal p,boolean editar){if(p==null||p.accesoRecuperacion()||!p.alcanceInstitucional()||p.institucionId()==null||p.usuarioId()==null||p.authorities().stream().noneMatch(a->a.getAuthority().equals("PORTAL_IDENTIDAD_ADMINISTRAR")||!editar&&a.getAuthority().equals("PORTAL_IDENTIDAD_LEER")))throw new AccessDeniedException("Se requiere permiso de Portales e identidad y alcance institucional.");}
 public boolean puedeEditar(UsuarioPrincipal p){return p!=null&&p.authorities().stream().anyMatch(a->a.getAuthority().equals("PORTAL_IDENTIDAD_ADMINISTRAR"));}
 @Transactional(readOnly=true) public Map<String,Object> institucion(UsuarioPrincipal p){autorizar(p,false);var rows=jdbc.queryForList("SELECT codigo,nombre FROM institucion WHERE id=? AND activo",p.institucionId());if(rows.isEmpty())throw new AccessDeniedException("La institución no está activa.");return rows.getFirst();}
 private Map<String,Object> institucion(String codigo){var rows=jdbc.queryForList("SELECT id,codigo,nombre FROM institucion WHERE codigo=? AND activo",codigo);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return rows.getFirst();}
 private Tema tema(Map<String,Object> i,PortalTipo p,Map<String,Object> r,Long publicada){return new Tema((String)i.get("codigo"),p,r==null?0:((Number)r.get("version")).longValue(),publicada,r==null?p.principal:(String)r.get("principal"),r==null?p.fondo:(String)r.get("fondo"),r==null?p.acento:(String)r.get("acento"),r==null||(Boolean)r.get("original"),r==null?(String)i.get("nombre"):(String)r.get("nombre"),r==null?null:(byte[])r.get("logo"),r==null?null:(String)r.get("oscuro_principal"),r==null?null:(String)r.get("oscuro_fondo"),r==null?null:(String)r.get("oscuro_acento"));}
 private Long publicada(long id,PortalTipo p){var rows=jdbc.queryForList("SELECT publicada_version FROM portal_identidad WHERE institucion_id=? AND portal=?",id,p.codigo);return rows.isEmpty()||rows.getFirst().get("publicada_version")==null?null:((Number)rows.getFirst().get("publicada_version")).longValue();}
 @Transactional(readOnly=true) public Tema borrador(UsuarioPrincipal p,PortalTipo tipo){autorizar(p,false);var i=institucion(p);var rows=jdbc.queryForList("SELECT r.* FROM portal_identidad_revision r JOIN portal_identidad d USING(institucion_id,portal) WHERE r.institucion_id=? AND r.portal=? AND r.version=d.version",p.institucionId(),tipo.codigo);var t=tema(i,tipo,rows.isEmpty()?null:rows.getFirst(),publicada(p.institucionId(),tipo));return rows.isEmpty()?new Tema(t.codigo(),tipo,0,t.publicadaVersion(),t.principal(),t.fondo(),t.acento(),true,t.nombre(),logoActual(p.institucionId(),t.codigo()),null,null,null):t;}
 @Transactional(readOnly=true) public Tema publico(String codigo,PortalTipo tipo){var i=institucion(codigo);long id=((Number)i.get("id")).longValue();Long version=publicada(id,tipo);var rows=version==null?List.<Map<String,Object>>of():jdbc.queryForList("SELECT * FROM portal_identidad_revision WHERE institucion_id=? AND portal=? AND version=? AND publicado_en IS NOT NULL",id,tipo.codigo,version);return tema(i,tipo,rows.isEmpty()?null:rows.getFirst(),version);}
 @Transactional(readOnly=true) public Tema revision(UsuarioPrincipal p,PortalTipo tipo,long version){autorizar(p,false);var rows=jdbc.queryForList("SELECT * FROM portal_identidad_revision WHERE institucion_id=? AND portal=? AND version=?",p.institucionId(),tipo.codigo,version);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return tema(institucion(p),tipo,rows.getFirst(),publicada(p.institucionId(),tipo));}
 @Transactional(readOnly=true) public List<Map<String,Object>> historial(UsuarioPrincipal p,PortalTipo tipo){autorizar(p,false);var rows=jdbc.queryForList("SELECT r.version,r.principal,r.fondo,r.acento,r.original,r.oscuro_principal,r.oscuro_fondo,r.oscuro_acento,r.guardado_en,r.publicado_en,u.username guardado_por FROM portal_identidad_revision r JOIN usuario u ON u.id=r.guardado_por WHERE r.institucion_id=? AND r.portal=? ORDER BY r.version DESC LIMIT 50",p.institucionId(),tipo.codigo);var zone=java.time.ZoneId.of(jdbc.queryForObject("SELECT zona_horaria FROM institucion WHERE id=?",String.class,p.institucionId()));rows.forEach(r->r.computeIfPresent("guardado_en",(k,v)->((java.sql.Timestamp)v).toInstant().atZone(zone)));return rows;}
 public void guardar(UsuarioPrincipal p,PortalTipo tipo,PortalTemaForm f){autorizar(p,true);if(!f.isOscuroValido()||!PortalColores.valido(f.getPrincipal())||!PortalColores.valido(f.getFondo())||!PortalColores.valido(f.getAcento()))throw new ReglaNegocioException("Escribe los colores con formato hexadecimal, por ejemplo #187D43.");var i=institucion(p);var logo=logoActual(p.institucionId(),(String)i.get("codigo"));guardarCopia(p,tipo,f,(String)i.get("nombre"),logo);}
 private void guardarCopia(UsuarioPrincipal p,PortalTipo tipo,PortalTemaForm f,String nombre,byte[] logo){
  jdbc.queryForObject("SELECT id FROM institucion WHERE id=? FOR UPDATE",Long.class,p.institucionId());jdbc.update("INSERT INTO portal_identidad(institucion_id,portal) VALUES(?,?) ON CONFLICT DO NOTHING",p.institucionId(),tipo.codigo);long actual=jdbc.queryForObject("SELECT version FROM portal_identidad WHERE institucion_id=? AND portal=? FOR UPDATE",Long.class,p.institucionId(),tipo.codigo);if(actual!=f.getVersion())throw new ReglaNegocioException("El diseño cambió en otra pestaña. Recarga antes de guardar; no se sustituyó nada.");
  jdbc.update("INSERT INTO portal_identidad_revision(institucion_id,portal,version,principal,fondo,acento,original,nombre,logo,guardado_por,oscuro_principal,oscuro_fondo,oscuro_acento) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",p.institucionId(),tipo.codigo,actual+1,f.getPrincipal().toLowerCase(Locale.ROOT),f.getFondo().toLowerCase(Locale.ROOT),f.getAcento().toLowerCase(Locale.ROOT),f.isOriginal(),nombre,logo,p.usuarioId(),f.isOscuroPersonalizado()?f.getOscuroPrincipal().toLowerCase(Locale.ROOT):null,f.isOscuroPersonalizado()?f.getOscuroFondo().toLowerCase(Locale.ROOT):null,f.isOscuroPersonalizado()?f.getOscuroAcento().toLowerCase(Locale.ROOT):null);jdbc.update("UPDATE portal_identidad SET version=? WHERE institucion_id=? AND portal=?",actual+1,p.institucionId(),tipo.codigo);
 }
 public void publicar(UsuarioPrincipal p,PortalTipo tipo,long version){autorizar(p,true);jdbc.queryForObject("SELECT id FROM institucion WHERE id=? FOR UPDATE",Long.class,p.institucionId());var rows=jdbc.queryForList("SELECT version,publicada_version FROM portal_identidad WHERE institucion_id=? AND portal=? FOR UPDATE",p.institucionId(),tipo.codigo);if(rows.isEmpty()||version<=0||((Number)rows.getFirst().get("version")).longValue()!=version)throw new ReglaNegocioException("El borrador cambió. Recarga y revisa antes de publicar.");if(Objects.equals(rows.getFirst().get("publicada_version"),version))throw new ReglaNegocioException("Esta versión ya está publicada.");jdbc.update("UPDATE portal_identidad_revision SET publicado_por=?,publicado_en=CURRENT_TIMESTAMP WHERE institucion_id=? AND portal=? AND version=? AND publicado_en IS NULL",p.usuarioId(),p.institucionId(),tipo.codigo,version);jdbc.update("UPDATE portal_identidad SET publicada_version=? WHERE institucion_id=? AND portal=?",version,p.institucionId(),tipo.codigo);}
 public void restaurar(UsuarioPrincipal p,PortalTipo tipo,long revision,long actual){autorizar(p,true);var t=revision==0?tema(institucion(p),tipo,null,publicada(p.institucionId(),tipo)):revision(p,tipo,revision);var f=form(t);f.setVersion(actual);guardarCopia(p,tipo,f,t.nombre(),t.logo());}
 @Transactional(readOnly=true) public Tema identidadSesion(UsuarioPrincipal p,PortalTipo tipo){
  if(p==null||p.accesoRecuperacion()||p.institucionId()==null)throw new AccessDeniedException("Inicia sesión para consultar tu identidad institucional.");
  var rows=jdbc.queryForList("SELECT codigo FROM institucion WHERE id=? AND activo",p.institucionId());
  if(rows.isEmpty())throw new AccessDeniedException("La institución no está activa.");
  return publico((String)rows.getFirst().get("codigo"),tipo);
 }
 public static PortalTemaForm form(Tema t){var f=new PortalTemaForm();f.setVersion(t.version());f.setPrincipal(t.principal());f.setFondo(t.fondo());f.setAcento(t.acento());f.setOriginal(t.original());f.setOscuroPersonalizado(t.oscuroPrincipal()!=null);if(t.oscuroPrincipal()!=null){f.setOscuroPrincipal(t.oscuroPrincipal());f.setOscuroFondo(t.oscuroFondo());f.setOscuroAcento(t.oscuroAcento());}return f;}
 @Transactional(readOnly=true) public Map<String,String> coloresInstitucionales(UsuarioPrincipal p){autorizar(p,false);try{var code=(String)institucion(p).get("codigo");if(!haySitio(code))return Map.of();var s=sitios.publico(code);return Map.of("principal",s.getPrincipal(),"acento",s.getAcento());}catch(ResponseStatusException e){return Map.of();}}
 private boolean haySitio(String codigo){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM sitio_web_publicacion p JOIN institucion i ON i.id=p.institucion_id WHERE i.codigo=? AND i.activo)",Boolean.class,codigo));}
 private byte[] logoActual(Long id,String codigo){try{var i=instituciones.findById(id).orElseThrow();if(i.getLogoArchivoId()!=null){var a=archivos.findById(i.getLogoArchivoId()).orElse(null);if(a!=null&&a.getInstitucion().getId().equals(id)&&a.getEstado()==EstadoArchivo.DISPONIBLE&&a.getTipoMime().startsWith("image/")){try(var in=almacenamiento.abrir(a.getClaveAlmacenamiento()).getInputStream()){return png(in);}}}if(!haySitio(codigo))return null;var s=sitios.publico(codigo);Long image=s.getLogoId();if(s.getDiseno()!=null)image=s.getDiseno().getTodosComponentes().stream().filter(n->n.getTipo().equals("logo")&&n.getImagenId()!=null&&s.getDiseno().getImagenesComponentes().contains(n.getImagenId())).map(n->n.getImagenId()).findFirst().orElse(s.getDiseno().getBloques().stream().anyMatch(b->b.getTipo().equals("seccion"))?null:image);if(image!=null)return png(new ByteArrayInputStream(sitios.imagenPublica(codigo,image)));}catch(Exception e){/* Un logo ausente no impide configurar colores. No exponer archivos privados. */}return null;}
 private byte[] png(InputStream source)throws IOException{var bytes=source.readNBytes(5*1024*1024+1);if(bytes.length>5*1024*1024)return null;try(var in=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))){var readers=ImageIO.getImageReaders(in);if(!readers.hasNext())return null;var reader=readers.next();try{reader.setInput(in);int w=reader.getWidth(0),h=reader.getHeight(0);if(w<1||h<1||(long)w*h>25_000_000)return null;var original=reader.read(0);double ratio=Math.min(1,320d/Math.max(w,h));var scaled=new java.awt.image.BufferedImage(Math.max(1,(int)(w*ratio)),Math.max(1,(int)(h*ratio)),java.awt.image.BufferedImage.TYPE_INT_ARGB);var g=scaled.createGraphics();g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION,java.awt.RenderingHints.VALUE_INTERPOLATION_BICUBIC);g.drawImage(original,0,0,scaled.getWidth(),scaled.getHeight(),null);g.dispose();var out=new ByteArrayOutputStream();ImageIO.write(scaled,"png",out);return out.toByteArray();}finally{reader.dispose();}}}
}
